$('#cameraSheet').onclick=()=>$('#sheetCameraInput').click();$('#librarySheet').onclick=()=>$('#sheetLibraryInput').click();$$('.open-sheet').forEach(b=>b.onclick=()=>{S.activeSheetId=b.dataset.id;save();currentTab='study';render()});$$('.review-sheet').forEach(b=>b.onclick=()=>{S.activeSheetId=b.dataset.id;save();renderOCRReview(allWords(),false)});setPartner('필요한 시험지를 여기서 골라볼까?','note')
