async function preflightImage(file){
 if(!file||file.size<=0)throw new Error('빈 파일이에요.');if(!/^image\//.test(file.type||''))throw new Error('이미지 파일을 선택해 주세요.');if(file.size>20*1024*1024)throw new Error('사진이 너무 커요. 20MB 이하 사진을 사용해 주세요.');
 let bmp;try{bmp=await createImageBitmap(file,{imageOrientation:'from-image'})}catch{throw new Error('사진을 열 수 없어요. 다른 사진으로 다시 시도해 주세요.')}
 const short=Math.min(bmp.width,bmp.height),long=Math.max(bmp.width,bmp.height),warnings=[];if(short<700)warnings.push('해상도가 낮아요');if(long<1200)warnings.push('글자가 작게 보일 수 있어요');const ratio=long/Math.max(1,short);if(ratio>4.5)warnings.push('사진 비율이 너무 길어요');return {width:bmp.width,height:bmp.height,warnings,quality:warnings.length?'확인 필요':'양호'}
}
function ensureCaptureSession(){
 if(!S.captureSession||S.captureSession.status!=="OPEN")S.captureSession={sessionId:`capture-${Date.now()}`,status:"OPEN",createdAt:nowISO(),updatedAt:nowISO(),pages:[],analysisBatches:[],lastCommittedAt:""};
 S.captureSession.pages=Array.isArray(S.captureSession.pages)?S.captureSession.pages:[];
 S.captureSession.analysisBatches=Array.isArray(S.captureSession.analysisBatches)?S.captureSession.analysisBatches:[];
 return S.captureSession;
}
function capturePageKey(sessionId,pageId){return `capture:${sessionId}:${pageId}`}
async function captureFiles(files,sourceType="camera"){
 const list=[...(files||[])].filter(Boolean);if(!list.length)return;
 const session=ensureCaptureSession();let saved=0,failed=0;
 for(const file of list){
  try{
   const q=await preflightImage(file),pageId=`page-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,assetKey=capturePageKey(session.sessionId,pageId);
   await dbSet(assetKey,file);
   session.pages.push({pageId,assetKey,sourceType,fileName:file.name||"",mime:file.type||"image/jpeg",size:file.size,width:q.width,height:q.height,quality:q.quality,warnings:q.warnings,capturedAt:nowISO(),analyzedAt:""});
   saved++;
  }catch(e){failed++;toast(e.message||"사진을 저장하지 못했어요.")}
 }
 session.updatedAt=nowISO();save();
 const cam=$("#sheetCameraInput"),lib=$("#sheetLibraryInput");if(cam)cam.value="";if(lib)lib.value="";
 if(saved){viewStack=[];pushView(()=>renderCaptureSession(failed?`${saved}장 저장 · ${failed}장 제외`:"촬영 즉시 저장 완료"));setPartner("좋아, 다음 장도 이어서 가자.","note")}
}
function renderCaptureSession(notice=""){
 const session=ensureCaptureSession(),pages=session.pages||[],pending=pages.filter(p=>!p.analyzedAt);
 $("#view").innerHTML=`<section class="capture-shell"><div class="hero-kicker"><span>CAPTURE SESSION</span><span>${session.status}</span></div><h2>시험지 연속 촬영</h2><p>${notice||"촬영하면 확인 화면 없이 바로 임시 저장됩니다. 필요한 만큼 찍은 뒤 ‘여기까지 분석’을 누르세요."}</p><div class="capture-summary"><b>${pages.length}장 저장</b><span>${pending.length}장 분석 대기</span></div><div class="capture-list">${pages.map((p,i)=>`<div class="capture-page"><div><b>${i+1}번째 사진</b><small>${p.width}×${p.height} · ${Math.round((p.size||0)/1024)}KB</small></div><span class="badge ${p.analyzedAt?"good":p.warnings?.length?"weak":"mid"}">${p.analyzedAt?"분석됨":p.warnings?.length?"확인 필요":"저장됨"}</span></div>`).join("")||"<p>아직 저장된 사진이 없어요.</p>"}</div><div class="btn-row" style="margin-top:13px"><button class="btn primary" id="captureMore" type="button">계속 촬영</button><button class="btn secondary" id="captureLibrary" type="button">사진 추가</button></div><button class="btn dark full" id="analyzeBatch" style="margin-top:8px" type="button" ${pending.length?"":"disabled"}>여기까지 분석</button><button class="btn secondary full" id="finishCapture" style="margin-top:8px" type="button">촬영 끝내기</button>${S.activeSheetId&&sheet()?'<button class="btn secondary full" id="goActiveSheet" style="margin-top:8px" type="button">현재 시험지 학습으로</button>':""}</section>`;
 $("#captureMore").onclick=()=>$("#sheetCameraInput").click();$("#captureLibrary").onclick=()=>$("#sheetLibraryInput").click();$("#analyzeBatch").onclick=analyzeCaptureBatch;
 $("#finishCapture").onclick=()=>{session.status="CLOSED";session.closedAt=nowISO();session.updatedAt=nowISO();save();currentTab="sheets";viewStack=[];render();toast("촬영 세션을 종료했어요.")};
 $("#goActiveSheet")?.addEventListener("click",()=>{currentTab="study";viewStack=[];render()});
}
async function analyzeCaptureBatch(){
 const session=ensureCaptureSession(),targets=(session.pages||[]).filter(p=>!p.analyzedAt);
 if(!targets.length)return toast("새로 분석할 사진이 없어요.");
 if(!navigator.onLine)return toast("OCR 분석은 온라인 연결이 필요해요. 저장된 사진은 그대로 유지됩니다.");
 if(!runtimeApiKey)return pushView(()=>renderManualEntry("API Key가 없어 OCR을 실행하지 않았어요. 저장된 촬영 세션은 유지됩니다."));
 $("#view").innerHTML=`<section class="card"><div class="hero-kicker"><span>OCR BATCH</span><span>${targets.length} page</span></div><h2>여기까지 분석 중</h2><p id="ocrStage">SEE · 각 사진에서 실제 보이는 문자열만 확인 중</p><div class="progress" style="margin-top:16px"><span id="ocrProgress" style="width:8%"></span></div></section>`;
 try{
  const seen=[];
  for(let i=0;i<targets.length;i++){
   const p=targets[i],file=await dbGet(p.assetKey);if(!file)throw new Error(`${i+1}번째 저장 사진을 찾을 수 없어요.`);
   const img=await normalizedImageBase64(file),seePrompt=`사진에 실제로 보이는 영어 단어와 한글 뜻만 행 순서대로 전사하세요. 원본에 없는 단어를 만들지 말고, 예문/힌트/정답 추측을 하지 마세요. 불확실하면 confidence를 low로 표시하세요. JSON만 출력: {"rows":[{"eng":"...","kor":"...","confidence":"high|medium|low"}]}`,see=await gemini(seePrompt,img.b64,img.mime);
   (see.rows||[]).forEach(r=>seen.push({...r,sourcePageId:p.pageId}));$("#ocrProgress").style.width=`${Math.round(8+52*(i+1)/targets.length)}%`;
  }
  $("#ocrStage").textContent="PAIR · 전체 촬영분에서 단어와 뜻의 대응 확인 중";
  const pairPrompt=`아래 SEE OCR 행만 사용해 영어 단어-한국어 뜻의 짝을 검증하세요. 원본에 없는 새 단어를 만들지 마세요. 헤더/번호/잡음은 제외하고 원래 순서를 유지하세요. 애매한 행은 low로 남기세요. sourcePageId를 유지하세요. JSON만 출력: {"rows":[{"eng":"...","kor":"...","confidence":"high|medium|low","sourcePageId":"..."}]}\nSEE:\n${JSON.stringify({rows:seen})}`;
  const paired=await gemini(pairPrompt),rows=(paired.rows||seen).filter(x=>x.eng||x.kor).map((x,i)=>normalizeWord({id:`ocr-${Date.now()}-${i}`,eng:x.eng,kor:x.kor,confidence:x.confidence||"medium",needsReview:x.confidence==="low",sourcePageId:x.sourcePageId},i));
  if(!rows.length)throw new Error("단어와 뜻을 찾지 못했어요.");
  const batchId=`batch-${Date.now()}`;targets.forEach(p=>p.analyzedAt=nowISO());session.analysisBatches.push({batchId,pageIds:targets.map(p=>p.pageId),createdAt:nowISO(),rowCount:rows.length});session.updatedAt=nowISO();
  S.ocrDraft={createdAt:nowISO(),captureSessionId:session.sessionId,batchId,pageIds:targets.map(p=>p.pageId),rows};save();$("#ocrProgress").style.width="100%";renderOCRReview(rows,true);
 }catch(e){toast(`OCR 실패: ${e.message||"다시 시도해 주세요."}`);renderCaptureSession("분석에 실패했지만 촬영 원본과 세션은 그대로 보존됐어요.")}
}
async function normalizedImageBase64(file,maxLong=2400){const bmp=await createImageBitmap(file,{imageOrientation:'from-image'}),scale=Math.min(1,maxLong/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bmp,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.9));return new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res({b64:String(fr.result).split(',')[1],mime:'image/jpeg'});fr.onerror=()=>rej(fr.error);fr.readAsDataURL(blob)})}
async function gemini(prompt,b64,mime){const parts=[{text:prompt}];if(b64)parts.push({inlineData:{mimeType:mime,data:b64}});const model=encodeURIComponent(S.settings.geminiModel||'gemini-2.5-flash'),r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':runtimeApiKey},body:JSON.stringify({contents:[{parts}],generationConfig:{responseMimeType:'application/json'}})});if(!r.ok){if(r.status===401||r.status===403)throw new Error('API 인증을 확인해 주세요.');if(r.status===429)throw new Error('요청이 많아요. 잠시 후 다시 시도해 주세요.');throw new Error(`네트워크/API 오류 ${r.status}`)}const j=await r.json(),txt=j.candidates?.[0]?.content?.parts?.[0]?.text||'{}';return JSON.parse(txt)}
function renderManualEntry(message='단어와 뜻을 직접 입력할 수 있어요.'){renderOCRReview([{id:`manual-${Date.now()}`,eng:'',kor:'',confidence:'manual',needsReview:true}],true,message)}
function renderOCRReview(rows,isDraft=false,message=""){
 let data=rows.map(normalizeWord);
 $("#view").innerHTML=`<section class="card"><div class="hero-kicker"><span>REVIEW BEFORE COMMIT</span><span>${data.length}개</span></div><h2>OCR 결과 확인</h2><p>${message||`${data.length}개를 찾았어요. ‘확인 필요’ 행은 직접 확인 완료해야 학습에 포함됩니다.`}</p><div class="table" id="ocrRows" style="margin-top:12px"></div><div class="btn-row" style="margin-top:13px"><button class="btn secondary" id="addOcrRow" type="button">행 추가</button><button class="btn primary" id="commitSheet" type="button">시험지 만들기</button></div></section>`;
 const draw=()=>{
  $("#ocrRows").innerHTML=data.map((w,i)=>`<div class="row review-row" data-i="${i}"><input class="eng" value="${esc(w.eng)}" aria-label="${i+1}번 영어 단어"><input class="kor" value="${esc(w.kor)}" aria-label="${i+1}번 뜻"><span class="badge ${w.needsReview?"weak":"good"}">${w.needsReview?"확인 필요":"확인"}</span>${w.needsReview?`<button class="review-confirm" data-confirm="${i}" type="button">확인 완료</button>`:""}<button class="row-delete" data-del="${i}" type="button" aria-label="${i+1}번 행 삭제">×</button></div>`).join("");
  $$("[data-del]").forEach(b=>b.onclick=()=>{data.splice(Number(b.dataset.del),1);draw()});
  $$("[data-confirm]").forEach(b=>b.onclick=()=>{const i=Number(b.dataset.confirm);data[i].needsReview=false;data[i].reviewConfirmed=true;draw()});
 };
 draw();
 $("#addOcrRow").onclick=()=>{data.push(normalizeWord({id:`manual-${Date.now()}`,eng:"",kor:"",confidence:"manual",needsReview:true},data.length));draw()};
 $("#commitSheet").onclick=()=>{
  const out=$$("#ocrRows .row").map((r,i)=>{const eng=$(".eng",r).value.trim(),kor=$(".kor",r).value.trim(),edited=eng!==String(data[i].eng||"").trim()||kor!==String(data[i].kor||"").trim();return normalizeWord({...data[i],eng,kor,needsReview:!!data[i].needsReview,manuallyEdited:!!data[i].manuallyEdited||edited,reviewConfirmed:!!data[i].reviewConfirmed},i)}).filter(x=>x.eng&&x.kor);
  if(!out.length)return toast("단어와 뜻을 한 개 이상 입력해 주세요.");
  const unresolved=out.filter(x=>x.needsReview).length,newId=isDraft?`sheet-${Date.now()}`:sheet().sheetId,capturePages=S.ocrDraft?.pageIds?.length||1,newSheet={sheetId:newId,title:isDraft?`${new Date().toLocaleDateString("ko-KR")} 시험지`:sheet().title,createdAt:isDraft?nowISO():sheet().createdAt,updatedAt:nowISO(),testDate:"",sourceType:isDraft?(S.ocrDraft?.captureSessionId?"capture-session":"photo"):"existing",sourceCount:isDraft?capturePages:(sheet().sourceCount||0),status:unresolved?"REVIEW_REQUIRED":"READY",caseMastery:0,items:out,recognitionMeta:{reviewedAt:nowISO(),count:out.length,unresolved,captureSessionId:S.ocrDraft?.captureSessionId||"",batchId:S.ocrDraft?.batchId||""}};
  if(isDraft){S.sheets.unshift(newSheet);S.activeSheetId=newId}else Object.assign(sheet(),newSheet);
  if(S.captureSession&&S.ocrDraft?.captureSessionId===S.captureSession.sessionId){S.captureSession.lastCommittedAt=nowISO();S.captureSession.updatedAt=nowISO()}
  S.ocrDraft=null;S.learning=clone(DEFAULT_STATE.learning);S.codeRed=clone(DEFAULT_STATE.codeRed);save();
  toast(unresolved?`저장 완료 · 확인 필요 ${unresolved}개는 학습에서 제외돼요.`:"시험지 저장 완료");
  if(S.captureSession?.status==="OPEN"){viewStack=[];renderCaptureSession("분석 결과를 저장했어요. 촬영 세션은 계속 열려 있습니다.")}else{currentTab="study";viewStack=[];render()}
 };
 setPartner("확실한 건 두고, 애매한 행만 같이 확인해보자.","note")
}
function resumeCurrentLearning(){const st=sheet()?.status||"READY";if(st==="CODE_RED_READY"){viewStack=[];return renderCodeRed()}if(st==="RETRACE_REQUIRED"){viewStack=[];return renderRetrace()}if(st==="TEST_READY"||st==="COMPLETED"){viewStack=[];return renderComplete()}const phase=S.learning.phase||"first";const map={first:renderFirstContact,meaning:renderMeaningCheck,connection:renderConnection,weak:renderWeak,code:renderCodeRed,done:renderComplete};viewStack=[];(map[phase]||renderFirstContact)()}
function renderLearningHub(){const ws=validWords();if(!ws.length)return renderSheets();const sh=sheet(),weak=ws.filter(w=>weakScore(w)>0).length,resumable=["LEARNING","CODE_RED_READY","RETRACE_REQUIRED"].includes(sh.status);$('#view').innerHTML=`<section class="learning-shell"><div class="learn-head"><div><span class="phase-chip">${stateLabel(sh.status)}</span><h2 style="margin:5px 0 0">${esc(sh.title)}</h2></div><div style="text-align:right"><b>${ws.length}단어</b><small style="display:block">취약 ${weak}개</small></div></div><div class="progress" style="margin-top:10px"><span style="width:${learningProgress()}%"></span></div>${resumable?'<button class="btn primary full" id="resumeLearning" style="margin-top:10px" type="button">이어서 학습</button>':''}<div class="section-title"><h2>학습 미션</h2><span>보고 → 뜻 → 연결 → 취약 → 검증</span></div><div class="grid2"><button class="mission-card" id="phaseFirst" type="button"><h3>FIRST FIND</h3><p>보고, 듣고, 뜻과 철자 형태를 익혀요.</p></button><button class="mission-card" id="phaseMeaning" type="button"><h3>MEANING CLUE</h3><p>영어↔뜻을 양방향 4지선다로 확인해요.</p></button><button class="mission-card" id="phaseConnect" type="button"><h3>CONNECTION TRAIL</h3><p>단어와 뜻을 빠르게 타일로 연결해요.</p></button><button class="mission-card" id="phaseWeak" type="button"><h3>HIDDEN WORDS</h3><p>오답·PASS·힌트 단어를 더 자주 만나요.</p></button></div><button class="btn danger full" id="phaseCode" style="margin-top:9px" type="button">FINAL SEEK · 전체 철자 최종 검증</button></section>`;$('#resumeLearning')?.addEventListener('click',resumeCurrentLearning);$('#phaseFirst').onclick=()=>pushView(renderFirstContact);$('#phaseMeaning').onclick=()=>pushView(renderMeaningCheck);$('#phaseConnect').onclick=()=>pushView(renderConnection);$('#phaseWeak').onclick=()=>pushView(renderWeak);$('#phaseCode').onclick=()=>startCodeRed(false);setPartner('먼저 충분히 익히고, 약한 단어를 더 보고, 마지막에 전체 철자를 확인하자.','default')}
function renderFirstContact(){const ws=validWords(),i=S.learning.firstIndex%ws.length,w=ws[i];sheet().status='LEARNING';S.learning.phase='first';save();$('#view').innerHTML=`<section class="learning-shell"><div class="learn-head"><div><span class="phase-chip">FIRST FIND</span><h2 style="margin:5px 0 0">신규 단어 습득</h2></div><b>${i+1}/${ws.length}</b></div><div class="progress" style="margin-top:9px"><span style="width:${Math.round((i+1)/ws.length*100)}%"></span></div><section class="card word-card"><div class="eng">${esc(w.eng)}</div><button class="circle-btn" id="speakWord" type="button" style="margin:10px auto 0">발음</button><div class="kor">${esc(w.kor)}</div>${w.example?`<div class="example">${esc(w.example)}</div>`:''}<div class="btn-row" style="margin-top:17px"><button class="btn secondary" id="firstUnsure" type="button">아직 헷갈려</button><button class="btn primary" id="firstNext" type="button">다음 단어</button></div></section></section>`;$('#speakWord').onclick=()=>speakWord(w.eng);$('#firstUnsure').onclick=()=>{w.wrong=(w.wrong||0)+1;advanceFirst(false)};$('#firstNext').onclick=()=>advanceFirst(true);setPartner('지금은 시험이 아니야. 소리와 뜻, 철자 모양을 편하게 연결해둬.','default')}
function advanceFirst(ok){const ws=validWords();markStudy(ok?2:1);S.learning.firstIndex++;if(S.learning.firstIndex>=ws.length){S.learning.firstIndex=0;S.learning.phase='meaning';save();renderMeaningCheck()}else{save();renderFirstContact()}}
function optionLabel(w,field){return String(field==='kor'?w.kor:w.eng).trim().replace(/\s+/g,' ')}
function choiceOptions(correct,field){const correctLabel=optionLabel(correct,field).toLowerCase(),seen=new Set([correctLabel]),pool=shuffle(validWords().filter(x=>x.id!==correct.id)).filter(x=>{const label=optionLabel(x,field).toLowerCase();if(!label||seen.has(label))return false;seen.add(label);return true});return shuffle([correct,...pool.slice(0,3)]).map(x=>({id:x.id,label:optionLabel(x,field)}))}
function renderMeaningCheck(){const ws=validWords(),i=S.learning.meaningIndex%ws.length,w=ws[i],reverse=i%2===1,field=reverse?'eng':'kor',prompt=reverse?w.kor:w.eng,opts=choiceOptions(w,field);S.learning.phase='meaning';S.learning.meaningStartedAt=Date.now();sheet().status='LEARNING';save();$('#view').innerHTML=`<section class="learning-shell"><div class="learn-head"><div><span class="phase-chip">MEANING CLUE</span><h2 style="margin:5px 0 0">${reverse?'뜻 → 영어':'영어 → 뜻'}</h2></div><b>${i+1}/${ws.length}</b></div><section class="card word-card"><div class="eng" style="font-size:${reverse?'23px':'31px'}">${esc(prompt)}</div><div class="choice-grid">${opts.map(o=>`<button class="choice" data-choice="${esc(o.id)}" type="button">${esc(o.label)}</button>`).join('')}</div></section></section>`;$$('[data-choice]').forEach(b=>b.onclick=()=>meaningAnswer(b,w,b.dataset.choice===w.id));setPartner('정답을 외워 찍기보다, 영어와 뜻의 연결을 빠르게 확인해보자.','focus')}
function meaningAnswer(btn,w,ok){$$('[data-choice]').forEach(b=>b.disabled=true);btn.classList.add(ok?'correct':'wrong');const elapsedMs=Math.max(0,Date.now()-Number(S.learning.meaningStartedAt||Date.now())),slow=ok&&elapsedMs>=7000;if(!ok){w.wrong=(w.wrong||0)+1;setPartner('이 단어는 추적 목록에 넣어둘게. 뒤에서 더 자주 만나자.','note')}else{w.learningStats=w.learningStats||{};if(slow)w.learningStats.slowCorrect=(w.learningStats.slowCorrect||0)+1;S.learning.combo++;S.learning.flow=Math.min(6,S.learning.flow+1)}S.learning.history.push({at:nowISO(),mode:'meaning',wordId:w.id,result:ok?(slow?'SLOW_CORRECT':'CORRECT'):'WRONG',elapsedMs});markStudy(ok?3:1);setTimeout(()=>{S.learning.meaningIndex++;if(S.learning.meaningIndex>=validWords().length){S.learning.meaningIndex=0;S.learning.phase='connection';save();renderConnection()}else{save();if(ok&&S.learning.combo>0&&S.learning.combo%5===0)triggerFever(()=>renderMeaningCheck());else renderMeaningCheck()}},350)}
function connectionSet(){const words=validWords(),baseRounds=Math.ceil(words.length/4),round=S.learning.connectionRound;if(round<baseRounds)return words.slice(round*4,Math.min(words.length,round*4+4));return [...words].filter(w=>weakScore(w)>0).sort((a,b)=>weakScore(b)-weakScore(a)).slice(0,Math.min(4,words.length))}
function renderConnection(){const set=connectionSet();selectedTile=null;S.learning.phase='connection';save();const left=shuffle(set),right=shuffle(set);$('#view').innerHTML=`<section class="learning-shell"><div class="learn-head"><div><span class="phase-chip">CONNECTION TRAIL</span><h2 style="margin:5px 0 0">단어와 뜻 연결</h2></div><b>Round ${S.learning.connectionRound+1}</b></div><section class="card"><p>왼쪽 영어 하나와 오른쪽 뜻 하나를 차례로 선택하세요.</p><div class="tile-board"><div>${left.map(w=>`<button class="tile tile-eng" data-id="${w.id}" data-side="eng" type="button">${esc(w.eng)}</button>`).join('')}</div><div>${right.map(w=>`<button class="tile tile-kor" data-id="${w.id}" data-side="kor" type="button">${esc(w.kor)}</button>`).join('')}</div></div><button class="btn primary full" id="connectionNext" style="margin-top:12px" type="button" disabled>다음 라운드</button></section></section>`;$$('.tile').forEach(b=>b.onclick=()=>tilePick(b));setPartner('이번엔 단어와 뜻을 빠르게 연결해보자. 틀려도 바로 다음 단서로 가면 돼.','play')}
function tilePick(btn){if(btn.classList.contains('matched'))return;if(!selectedTile){selectedTile=btn;btn.classList.add('selected');return}if(selectedTile.dataset.side===btn.dataset.side){selectedTile.classList.remove('selected');selectedTile=btn;btn.classList.add('selected');return}const ok=selectedTile.dataset.id===btn.dataset.id,id=btn.dataset.id;if(ok){$$(`.tile[data-id="${id}"]`).forEach(x=>x.classList.add('matched'));S.learning.combo++;S.learning.flow=Math.min(6,S.learning.flow+1);markStudy(2)}else{const w=validWords().find(x=>x.id===selectedTile.dataset.id);if(w)w.wrong=(w.wrong||0)+1;markStudy(1);setPartner('연결이 살짝 엇갈렸네. 두 단서를 다시 보고 이어가자.','think')}selectedTile.classList.remove('selected');selectedTile=null;if($$('.tile:not(.matched)').length===0){$('#connectionNext').disabled=false;$('#connectionNext').onclick=()=>{const words=validWords(),baseRounds=Math.ceil(words.length/4),hasWeak=words.some(w=>weakScore(w)>0),lastRound=baseRounds+(hasWeak?1:0)-1;S.learning.connectionRound++;if(S.learning.connectionRound>lastRound){S.learning.connectionRound=0;S.learning.phase='weak';save();renderWeak()}else{save();renderConnection()}}}}
function renderWeak(){const ordered=[...validWords()].sort((a,b)=>weakScore(b)-weakScore(a)),weak=ordered.filter(w=>weakScore(w)>0),top=(weak.length?weak:ordered).slice(0,Math.min(6,ordered.length));S.learning.phase='weak';save();$('#view').innerHTML=`<section class="learning-shell"><div class="learn-head"><div><span class="phase-chip">HIDDEN WORDS</span><h2 style="margin:5px 0 0">어려운 단어 집중</h2></div><b>${top.length}개</b></div><section class="card"><div class="flow-gauge">${[0,1,2,3,4,5].map(i=>`<i class="${i<S.learning.flow?'on':''}"></i>`).join('')}</div><div class="weak-list" style="margin-top:13px">${top.map(w=>`<div class="weak-item"><div><b>${esc(w.eng)}</b><div style="font-size:10px;color:#66736a">${esc(w.kor)}</div></div><span class="badge ${weakScore(w)>=8?'weak':'mid'}">${weakScore(w)>=8?'집중':'확인'}</span></div>`).join('')}</div><div class="btn-row" style="margin-top:13px"><button class="btn secondary" id="weakReplay" type="button">취약 단어 다시 보기</button><button class="btn danger" id="weakToCode" type="button">FINAL SEEK</button></div></section></section>`;$('#weakReplay').onclick=()=>{const first=top[0];S.learning.firstIndex=Math.max(0,validWords().findIndex(w=>w.id===first.id));save();renderFirstContact()};$('#weakToCode').onclick=()=>startCodeRed(false);setPartner('약한 단어에 시간을 더 쓰되, 전체 단어를 마지막 FINAL SEEK에서 전부 확인할게.','focus')}
function triggerFever(next){S.learning.fever=true;save();$('#view').innerHTML=`<section class="card fever-stage"><div class="food-rain"><i class="food" style="left:8%">PIZZA</i><i class="food">DONUT</i><i class="food">JUICE</i><i class="food">BURGER</i><i class="food">FRUIT</i></div><div style="position:relative;z-index:2;text-align:center;padding-top:54px"><h1 style="font-size:35px;margin:0;color:#4d783e">FEVER TIME</h1><p>연속 성공 보너스 · 학습 판정은 그대로</p><div class="flow-gauge" style="max-width:290px;margin:17px auto">${[0,1,2,3,4,5].map(()=>'<i class="on"></i>').join('')}</div><button class="btn primary" id="leaveFever" type="button">계속 학습</button></div></section>`;setPartner('흐름 좋네. 잠깐 축제다. 문제는 그대로 차분하게 가자.','fever',true);$('#leaveFever').onclick=()=>{S.learning.fever=false;S.learning.flow=0;save();next()}}
function blankCount(word){const n=word.length;return n<=5?Math.min(2,Math.max(1,n-2)):n<=8?3:Math.min(4,n-2)}
function makeCodeSession(w){const n=blankCount(w.eng),idx=shuffle([...w.eng].map((_,i)=>i)).slice(0,n).sort((a,b)=>a-b),real=idx.map((i,k)=>({id:`r${k}-${Math.random()}`,ch:w.eng[i].toLowerCase(),real:true})),required=new Set(real.map(x=>x.ch)),alphabet='abcdefghijklmnopqrstuvwxyz',fakes=[];while(fakes.length<Math.max(3,n)){const ch=alphabet[Math.floor(Math.random()*alphabet.length)];if(!required.has(ch))fakes.push({id:`f${fakes.length}-${Math.random()}`,ch,real:false})}return {word:w,blankIdx:idx,keys:shuffle([...real,...fakes]),answers:{},hintLevel:0,wrongAttempts:0,seconds:S.settings.pressureReduced?24:(w.eng.length<=5?15:w.eng.length<=8?18:21),start:Date.now()}}
function codeTargets(){const ws=validWords();if(S.codeRed.retryOnly){const set=new Set(S.codeRed.targetIds.length?S.codeRed.targetIds:S.codeRed.retrace);return ws.filter(w=>set.has(w.id))}return ws}
function startCodeRed(retryOnly=false){stopCodeTimer();const targets=retryOnly?validWords().filter(w=>S.codeRed.retrace.includes(w.id)):validWords();if(!targets.length)return toast('FINAL SEEK 대상 단어가 없어요.');const sh=sheet();sh.learningProvenance=sh.learningProvenance||{};sh.learningProvenance.startedAt=sh.learningProvenance.startedAt||nowISO();sh.learningProvenance.lastActivityAt=nowISO();sh.learningProvenance.seekAgainCycles=Number(sh.learningProvenance.seekAgainCycles||0)+(retryOnly?1:0);S.learning.phase='code';sh.status='CODE_RED_READY';S.codeRed.index=0;S.codeRed.retryOnly=retryOnly;S.codeRed.targetIds=targets.map(w=>w.id);if(!retryOnly){S.codeRed.results={};S.codeRed.retrace=[]}save();viewStack=[];renderCodeRed()}
function renderCodeRed(){const targets=codeTargets();if(S.codeRed.index>=targets.length)return finishCodeRed();const w=targets[S.codeRed.index];codeSession=makeCodeSession(w);selectedKey=null;const letters=[...w.eng].map((ch,i)=>codeSession.blankIdx.includes(i)?`<span class="slot-anchor">_</span>`:esc(ch)).join('');$('#view').innerHTML=`<section class="code-shell"><div class="code-head"><div><span class="code-label">FINAL SEEK</span><div class="code-instruction" style="margin-top:6px">${S.codeRed.retryOnly?'RE-CHECK':'ALL CURRENT WORDS'} · ${S.codeRed.index+1}/${targets.length}</div></div><div id="timeRing" class="time-ring" style="--p:100"><b><span id="timeText">${codeSession.seconds}</span>s</b></div></div><div class="code-word"><div>${letters}</div><div class="slots">${codeSession.blankIdx.map((_,n)=>`<button class="slot" data-slot="${n}" type="button" aria-label="${n+1}번째 빈칸"></button>`).join('')}</div></div><p class="code-instruction">Letter Key를 빈칸으로 끌거나, Key를 탭한 뒤 Slot을 탭하세요.</p><div class="key-tray">${codeSession.keys.map(k=>`<button draggable="true" class="letter-key" data-key="${k.id}" type="button">${esc(k.ch)}</button>`).join('')}</div><div class="btn-row"><button class="btn gold" id="codeHint" type="button">힌트</button><button class="btn secondary" id="undoCode" type="button">되돌리기</button><button class="btn danger" id="passCode" type="button">PASS</button></div></section>`;bindCodeRed();startCodeTimer();setPartner('진짜 철자 열쇠만 골라. 가짜도 섞여 있어.','radio')}
function bindCodeRed(){$$('.letter-key').forEach(k=>{k.onclick=()=>selectKey(k.dataset.key);k.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',k.dataset.key))});$$('.slot').forEach(s=>{s.onclick=()=>placeSelected(Number(s.dataset.slot));s.addEventListener('dragover',e=>e.preventDefault());s.addEventListener('drop',e=>{e.preventDefault();placeKey(e.dataTransfer.getData('text/plain'),Number(s.dataset.slot))})});$('#undoCode').onclick=undoCode;$('#codeHint').onclick=useCodeHint;$('#passCode').onclick=()=>recordCodeResult('PASS')}
function selectKey(id){selectedKey=id;$$('.letter-key').forEach(k=>k.classList.toggle('selected',k.dataset.key===id))}
function placeSelected(slot){if(selectedKey)placeKey(selectedKey,slot)}
function placeKey(keyId,slot){const key=codeSession.keys.find(k=>k.id===keyId);if(!key||key.used)return;const need=codeSession.word.eng[codeSession.blankIdx[slot]].toLowerCase();if(key.ch!==need){codeSession.wrongAttempts++;selectedKey=null;$$('.letter-key').forEach(k=>k.classList.remove('selected'));const el=$(`[data-key="${CSS.escape(keyId)}"]`);if(el){el.classList.remove('reject');void el.offsetWidth;el.classList.add('reject')}setPartner('가짜 열쇠였네. 원래 자리로 돌려둘게.','focus');return}const prev=codeSession.answers[slot];if(prev){const pk=codeSession.keys.find(k=>k.id===prev);if(pk)pk.used=false}codeSession.answers[slot]=key.id;key.used=true;selectedKey=null;updateCodeUI();if(Object.keys(codeSession.answers).length===codeSession.blankIdx.length)setTimeout(checkCodeAnswer,180)}
function updateCodeUI(){$$('.slot').forEach(s=>{const id=codeSession.answers[Number(s.dataset.slot)],key=codeSession.keys.find(k=>k.id===id);s.textContent=key?.ch||'';s.classList.toggle('filled',!!key)});$$('.letter-key').forEach(el=>{const key=codeSession.keys.find(x=>x.id===el.dataset.key);el.classList.toggle('used',!!key?.used);el.classList.remove('selected')})}
function undoCode(){const slots=Object.keys(codeSession.answers);if(!slots.length)return;const last=slots.at(-1),id=codeSession.answers[last],k=codeSession.keys.find(x=>x.id===id);if(k)k.used=false;delete codeSession.answers[last];updateCodeUI()}
function useCodeHint(){codeSession.hintLevel++;const unanswered=codeSession.blankIdx.map((_,i)=>i).filter(i=>!codeSession.answers[i]);if(!unanswered.length)return;const slot=unanswered[0],needed=codeSession.word.eng[codeSession.blankIdx[slot]].toLowerCase(),key=codeSession.keys.find(k=>!k.used&&k.ch===needed);if(!key)return;const el=$(`[data-key="${CSS.escape(key.id)}"]`);if(codeSession.hintLevel>=4){placeKey(key.id,slot);return}el?.classList.add('selected');if(codeSession.hintLevel===3){const target=$(`[data-slot="${slot}"]`);target?.classList.add('hint-target')}setPartner(codeSession.hintLevel===1?'필요한 열쇠 하나가 살짝 반응했어.':codeSession.hintLevel===2?'정답 열쇠를 조금 더 눈여겨봐.':'이 열쇠와 가까운 빈칸을 같이 봐.','hint')}
function checkCodeAnswer(){const built=codeSession.blankIdx.map((_,slot)=>codeSession.keys.find(k=>k.id===codeSession.answers[slot])?.ch||''),need=codeSession.blankIdx.map(i=>codeSession.word.eng[i].toLowerCase());if(built.every((x,i)=>x===need[i])){const elapsed=(Date.now()-codeSession.start)/1000,slow=elapsed>=codeSession.seconds*.7;recordCodeResult(codeSession.wrongAttempts>0?'WRONG':codeSession.hintLevel?'HINT_USED':slow?'SLOW_CORRECT':'CORRECT')}}
function recordCodeResult(type){stopCodeTimer();const w=codeSession.word,attempt={wordId:w.id,type,at:nowISO(),hintLevel:codeSession.hintLevel,wrongAttempts:codeSession.wrongAttempts};const sh=sheet();sh.learningProvenance=sh.learningProvenance||{};sh.learningProvenance.lastActivityAt=attempt.at;sh.learningProvenance.finalSeekAttempts=Number(sh.learningProvenance.finalSeekAttempts||0)+1;S.codeRed.results[w.id]=attempt;S.codeRed.history.push(attempt);w.learningStats=w.learningStats||{};w.learningStats.codeRedAttempts=(w.learningStats.codeRedAttempts||0)+1;if(['WRONG','PASS','TIMEOUT','HINT_USED'].includes(type)){if(!S.codeRed.retrace.includes(w.id))S.codeRed.retrace.push(w.id);if(type==='WRONG')w.wrong=(w.wrong||0)+1;if(type==='PASS')w.pass=(w.pass||0)+1;if(type==='TIMEOUT')w.learningStats.timeout=(w.learningStats.timeout||0)+1;if(type==='HINT_USED')w.hint=(w.hint||0)+1}else{if(type==='SLOW_CORRECT')w.learningStats.slowCorrect=(w.learningStats.slowCorrect||0)+1;S.learning.combo++;S.learning.flow=Math.min(6,S.learning.flow+1)}S.codeRed.index++;markStudy(['CORRECT','SLOW_CORRECT'].includes(type)?5:1);save();if(S.codeRed.index<codeTargets().length)renderCodeRed();else finishCodeRed()}
function startCodeTimer(){const total=codeSession.seconds;codeTimer=setInterval(()=>{const left=Math.max(0,total-(Date.now()-codeSession.start)/1000),pct=Math.round(left/total*100),ring=$('#timeRing'),txt=$('#timeText');if(!ring||!txt)return;ring.style.setProperty('--p',pct);txt.textContent=Math.ceil(left);ring.classList.toggle('warn',pct<=45&&pct>20);ring.classList.toggle('alert',pct<=20);if(left<=0)recordCodeResult('TIMEOUT')},150)}
function stopCodeTimer(){if(codeTimer){clearInterval(codeTimer);codeTimer=null}}
function finishCodeRed(){stopCodeTimer();const currentTargets=codeTargets(),passed=currentTargets.filter(w=>['CORRECT','SLOW_CORRECT'].includes(S.codeRed.results[w.id]?.type)).map(w=>w.id),sh=sheet();if(S.codeRed.retryOnly)S.codeRed.retrace=S.codeRed.retrace.filter(id=>!passed.includes(id));sh.learningProvenance=sh.learningProvenance||{};sh.learningProvenance.lastActivityAt=nowISO();sh.learningProvenance.lastTargetCount=currentTargets.length;sh.learningProvenance.remainingRetraceCount=S.codeRed.retrace.length;if(S.codeRed.retrace.length){sh.status='RETRACE_REQUIRED';save();return renderRetrace()}sh.caseMastery=100;sh.status='TEST_READY';sh.learningProvenance.completedAt=nowISO();sh.learningProvenance.completedWordCount=validWords().length;sh.learningProvenance.finalSeekResultCount=Object.keys(S.codeRed.results||{}).length;S.learning.phase='done';syncSheetToLexicon(sh);save();renderComplete()}
function renderRetrace(){const targets=validWords().filter(w=>S.codeRed.retrace.includes(w.id));$('#view').innerHTML=`<div class="section-title"><h2>SEEK AGAIN</h2><span>Fail → Learn Again → Recall Again</span></div><section class="card tint-leaf"><p>틀린 직후 같은 정답을 즉시 반복하지 않습니다. 뜻·발음·철자를 짧게 다시 본 뒤 해당 단어만 재검증합니다.</p><div class="retrace-list" style="margin-top:13px">${targets.map(w=>`<div class="retrace-item"><div><b>${esc(w.eng)}</b><span>${esc(w.kor)}</span></div><button class="circle-btn speak-retrace" data-word="${esc(w.eng)}" type="button">듣기</button></div>`).join('')}</div><button class="btn danger full" id="retryCode" style="margin-top:13px" type="button">이 단어만 다시 FINAL SEEK</button></section>`;$$('.speak-retrace').forEach(b=>b.onclick=()=>speakWord(b.dataset.word));$('#retryCode').onclick=()=>startCodeRed(true);setPartner('놓쳤다고 끝난 건 아니지. 다시 익힌 뒤 같은 단어만 재검증하자.','note')}
function renderComplete(){const old=selectPastMemoryEvent();if(old)markMemoryEventShown(old);$('#view').innerHTML=`<section class="card tint-leaf" style="text-align:center;padding:25px"><img src="${guideAsset('cheer')}" alt="" style="width:110px;height:110px;object-fit:contain;margin:0 auto 4px"><h1 style="margin:0">학습 준비 완료</h1><p>현재 시험지의 유효 단어를 FINAL SEEK와 SEEK AGAIN까지 확인했어요.</p><div class="grid3" style="margin-top:14px"><div class="status-pill"><b>100%</b><span>Trail Mastery</span></div><div class="status-pill"><b>${S.xp}</b><span>XP</span></div><div class="status-pill"><b>${memoryStrength()}%</b><span>Memory</span></div></div><button class="btn primary full" id="backHome" style="margin-top:14px" type="button">홈으로</button></section>${old?`<div class="section-title"><h2>지난 단어 다시 보기</h2><span>선택적 장기기억 이벤트</span></div><section class="card memory-event"><p>학습 흐름을 막지 않는 작은 확인이야. 건너뛰어도 불이익은 없어.</p><div class="bigword">${esc(old.canonicalSpelling)}</div><p style="text-align:center">${esc(old.sense)}</p><div class="btn-row" style="margin-top:12px"><button class="btn secondary" id="memorySkip" type="button">건너뛰기</button><button class="btn secondary" id="memoryNo" type="button">기억 안 나요</button><button class="btn primary" id="memoryYes" type="button">기억해요</button></div></section>`:''}`;$('#backHome').onclick=()=>{currentTab='home';viewStack=[];render()};if(old){$('#memorySkip').onclick=()=>toast('현재 학습 기록에는 영향이 없어요.');$('#memoryYes').onclick=()=>{old.lastSeen=nowISO();old.memoryStrength=Math.min(100,Number(old.memoryStrength||60)+10);old.nextReviewPriority=Math.max(0,100-old.memoryStrength);save();toast('기억 기록 이상 없음')};$('#memoryNo').onclick=()=>{old.lastSeen=nowISO();old.lastWrong=nowISO();old.memoryStrength=Math.max(10,Number(old.memoryStrength||60)-15);old.nextReviewPriority=Math.max(Number(old.nextReviewPriority||0),100-old.memoryStrength+15);save();toast('다음 복습 우선도를 조금 올렸어요.')}}setPartner('오늘 탐험 완료. 오늘 범위는 여기까지 찾았어.','cheer',true)}
function renderWords(){const ws=validWords();$('#view').innerHTML=`<div class="section-title"><h2>내 단어장</h2><span>${ws.length}개</span></div><section class="card">${ws.length?`<div class="weak-list">${[...ws].sort((a,b)=>weakScore(b)-weakScore(a)).map(w=>`<div class="weak-item"><div><b>${esc(w.eng)}</b><div style="font-size:10px;color:#66736a">${esc(w.kor)}</div></div><span class="badge ${weakScore(w)>=8?'weak':weakScore(w)>0?'mid':'good'}">${weakScore(w)>=8?'약함':weakScore(w)>0?'확인':'안정'}</span></div>`).join('')}</div>`:'<p>아직 단어가 없어요.</p>'}</section>`;setPartner('단어장은 지난 학습의 기록이야. 현재 시험지보다 앞서지는 않아.','note')}
function renderRecords(){const sh=sheet();$('#view').innerHTML=`<div class="section-title"><h2>기록</h2><span>Trail ≠ Memory</span></div><section class="card tint-sky"><div class="metric"><span>Trail Mastery</span><b>${sh.caseMastery||0}%</b></div><div class="metric"><span>Memory Strength</span><b>${memoryStrength()}%</b></div><div class="metric"><span>총 XP</span><b>${S.xp}</b></div><div class="metric"><span>연속 학습</span><b>${S.streak}일</b></div></section><div class="section-title"><h2>최근 학습</h2><span>${APP_REV}</span></div><section class="card">${S.sessions.length?S.sessions.slice(-7).reverse().map(x=>`<div class="metric"><span>${esc(x.date)}</span><b>${x.count}회</b></div>`).join(''):'<p>아직 기록이 없어요.</p>'}</section>`;setPartner('완료한 학습은 완료 상태 그대로야. 장기 기억은 따로 천천히 추적할게.','default')}
function exportData(){const copy=clone(S);delete copy.settings.geminiKey;const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`HIDE_SEEK_DATA_${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importData(file){try{const data=JSON.parse(await file.text()),m=migrate(data);if(!Array.isArray(m.sheets)||!m.sheets.length)throw new Error('시험지 데이터가 없어요.');S=m;save();toast('데이터를 불러왔어요.');$('#modalRoot').innerHTML='';render()}catch(e){toast(`불러오기 실패: ${e.message||'파일을 확인해 주세요.'}`)}}
function openSettings(){$('#modalRoot').innerHTML=`<div class="modal-back"><section class="modal"><div class="section-title"><h2>설정</h2><button class="circle-btn" id="closeSettings" type="button">닫기</button></div><div class="setting"><div><label>길잡이 음성</label><small>영어 단어 발음보다 우선하지 않습니다.</small></div><button class="switch ${S.settings.partnerVoice?'on':''}" data-toggle="partnerVoice" type="button"><i></i></button></div><div class="setting"><div><label>Reduced Motion</label><small>과한 움직임을 줄입니다.</small></div><button class="switch ${S.settings.reducedMotion?'on':''}" data-toggle="reducedMotion" type="button"><i></i></button></div><div class="setting"><div><label>긴장 연출 줄이기</label><small>FINAL SEEK 시간을 조금 넉넉하게 제공합니다.</small></div><button class="switch ${S.settings.pressureReduced?'on':''}" data-toggle="pressureReduced" type="button"><i></i></button></div><div class="setting"><div style="width:100%"><label>Gemini API Key</label><small>개인 테스트용 · 이번 브라우저 세션에만 보관. 공개 배포는 서버 프록시 권장.</small><input id="apiKey" class="input" type="password" value="${esc(runtimeApiKey)}" placeholder="API Key"></div></div><div class="setting"><div style="width:100%"><label>Gemini Model</label><input id="apiModel" class="input" value="${esc(S.settings.geminiModel)}"></div></div><div class="btn-row" style="margin-top:13px"><button class="btn secondary" id="exportData" type="button">데이터 내보내기</button><button class="btn secondary" id="importData" type="button">데이터 불러오기</button></div><button class="btn primary full" id="saveSettings" style="margin-top:8px" type="button">설정 저장</button><button class="btn secondary full" id="restartOnboarding" style="margin-top:8px" type="button">프로필/길잡이 다시 설정</button><p style="margin-top:10px">Build ${APP_REV} · Schema ${SCHEMA_VERSION}</p></section></div>`;$('#closeSettings').onclick=()=>$('#modalRoot').innerHTML='';$$('[data-toggle]').forEach(b=>b.onclick=()=>{const k=b.dataset.toggle;S.settings[k]=!S.settings[k];b.classList.toggle('on',S.settings[k]);save()});$('#saveSettings').onclick=()=>{runtimeApiKey=$('#apiKey').value.trim();sessionStorage.setItem(SESSION_API_KEY,runtimeApiKey);S.settings.geminiModel=$('#apiModel').value.trim()||'gemini-2.5-flash';save();$('#modalRoot').innerHTML='';toast('설정을 저장했어요. API Key는 세션에만 유지됩니다.')};$('#restartOnboarding').onclick=()=>{S.onboardingDone=false;S.onboardingStep=0;save();$('#modalRoot').innerHTML='';render()};$('#exportData').onclick=exportData;$('#importData').onclick=()=>$('#importDataInput').click()}
$('#settingsBtn').onclick=openSettings;$('#backBtn').onclick=goBack;$('#partnerVoiceBtn').onclick=()=>partnerSpeak();$('#profileCameraInput').addEventListener('change',e=>profilePicked(e.target.files[0]));$('#profileLibraryInput').addEventListener('change',e=>profilePicked(e.target.files[0]));$('#sheetCameraInput').addEventListener('change',e=>captureFiles(e.target.files,"camera"));$('#sheetLibraryInput').addEventListener('change',e=>captureFiles(e.target.files,"library"));$('#importDataInput').addEventListener('change',e=>importData(e.target.files[0]));$$('.nav-btn').forEach(b=>b.onclick=()=>{viewStack=[];stopCodeTimer();currentTab=b.dataset.tab;render()});if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));save();render();
